import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import {
  Box, Typography, Paper, Tabs, Tab, Button, CircularProgress,
  Chip, Avatar, Divider, Grid, Card, CardContent,
} from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import EditIcon from '@mui/icons-material/Edit';
import PersonIcon from '@mui/icons-material/Person';
import WorkIcon from '@mui/icons-material/Work';
import DescriptionIcon from '@mui/icons-material/Description';
import PaymentsIcon from '@mui/icons-material/Payments';
import WorkHistoryIcon from '@mui/icons-material/WorkHistory';
import BadgeIcon from '@mui/icons-material/Badge';
import CreditCardIcon from '@mui/icons-material/CreditCard';
import PhoneIcon from '@mui/icons-material/Phone';
import EmailIcon from '@mui/icons-material/Email';
import CalendarMonthIcon from '@mui/icons-material/CalendarMonth';
import BusinessIcon from '@mui/icons-material/Business';
import AccountTreeIcon from '@mui/icons-material/AccountTree';
import { useEmployee } from '../core/hooks/useEmployees';
import StatusBadge from '../core/components/ui/StatusBadge';
import BasicInfoTab from '../core/components/employee/BasicInfoTab';
import EmploymentTab from '../core/components/employee/EmploymentTab';
import DocumentsTab from '../core/components/employee/DocumentsTab';
import ReceiptsTab from '../core/components/employee/ReceiptsTab';
import WorkRecordTab from '../core/components/employee/WorkRecordTab';
import { toJalali } from '../core/utils/dateUtils';
import { formatPersianNumber, toPersianDigits } from '../core/utils/numberUtils';

const EmployeeProfilePage = () => {
  const { t } = useTranslation();
  const { id } = useParams();
  const navigate = useNavigate();
  const { data: employee, isLoading, error } = useEmployee(id);
  const [tabIndex, setTabIndex] = useState(0);

  if (isLoading) return <Box sx={{ textAlign: 'center', p: 8 }}><CircularProgress /></Box>;
  if (error || !employee) return (
    <Box sx={{ textAlign: 'center', p: 6 }}>
      <Typography color="error" variant="h5">{t('employees.not_found')}</Typography>
      <Button onClick={() => navigate('/employees')} sx={{ mt: 2 }}>{t('common.back')}</Button>
    </Box>
  );

  const e = employee;

  return (
    <Box>
      {/* Navigation */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
        <Button startIcon={<ArrowBackIcon />} onClick={() => navigate('/employees')}>{t('common.back')}</Button>
        <Button variant="contained" startIcon={<EditIcon />} onClick={() => navigate(`/employees/${id}/edit`)}>
          {t('common.edit')}
        </Button>
      </Box>

      {/* Enhanced Hero Card */}
      <Paper sx={{ mb: 3, position: 'relative', overflow: 'hidden' }}>
        {/* Decorative blobs */}
        <Box sx={{
          position: 'absolute', top: -80, left: -60, width: 250, height: 250,
          borderRadius: '50%', background: 'linear-gradient(135deg, rgba(99,102,241,0.16), rgba(236,72,153,0.1))',
          filter: 'blur(40px)',
        }} />
        <Box sx={{
          position: 'absolute', bottom: -80, right: -40, width: 200, height: 200,
          borderRadius: '50%', background: 'linear-gradient(135deg, rgba(16,185,129,0.1), rgba(59,130,246,0.08))',
          filter: 'blur(40px)',
        }} />

        <Box sx={{ position: 'relative', zIndex: 1, p: 3.5 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 3, flexWrap: 'wrap' }}>
            {/* Avatar */}
            <Avatar sx={{
              width: 96, height: 96, fontSize: 40, fontWeight: 800,
              background: 'linear-gradient(135deg, #6366f1, #ec4899)',
              boxShadow: '0 8px 32px rgba(99,102,241,0.35)',
              flexShrink: 0,
            }}>
              {e.first_name?.charAt(0)}{e.last_name?.charAt(0)}
            </Avatar>

            {/* Name + identity */}
            <Box sx={{ flex: 1, minWidth: 240 }}>
              <Typography variant="h4" fontWeight={800} sx={{ mb: 1 }}>
                {e.full_name}
              </Typography>
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                <Chip icon={<BadgeIcon sx={{ fontSize: 14 }} />} label={`کد پرسنلی: ${toPersianDigits(e.employee_id)}`} size="small" color="primary" variant="filled" />
                <Chip icon={<CreditCardIcon sx={{ fontSize: 14 }} />} label={`کد ملی: ${toPersianDigits(e.national_id)}`} size="small" variant="outlined" />
                <StatusBadge status={e.status} size="medium" />
              </Box>
            </Box>
          </Box>

          {/* Detail chips row */}
          <Divider sx={{ my: 2 }} />
          <Grid container spacing={1.5}>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <AccountTreeIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                <Box>
                  <Typography variant="caption" color="textSecondary" display="block">دپارتمان</Typography>
                  <Typography variant="body2" fontWeight={600}>{e.department_detail?.name || '—'}</Typography>
                </Box>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <WorkIcon sx={{ fontSize: 18, color: 'secondary.main' }} />
                <Box>
                  <Typography variant="caption" color="textSecondary" display="block">عنوان شغلی</Typography>
                  <Typography variant="body2" fontWeight={600}>{e.job_title_detail?.name || '—'}</Typography>
                </Box>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <BusinessIcon sx={{ fontSize: 18, color: 'success.main' }} />
                <Box>
                  <Typography variant="caption" color="textSecondary" display="block">محل استقرار</Typography>
                  <Typography variant="body2" fontWeight={600}>{e.work_location_detail?.name || '—'}</Typography>
                </Box>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <PhoneIcon sx={{ fontSize: 18, color: 'warning.main' }} />
                <Box>
                  <Typography variant="caption" color="textSecondary" display="block">موبایل</Typography>
                  <Typography variant="body2" fontWeight={600}>{toPersianDigits(e.mobile)}</Typography>
                </Box>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <EmailIcon sx={{ fontSize: 18, color: 'info.main' }} />
                <Box>
                  <Typography variant="caption" color="textSecondary" display="block">ایمیل</Typography>
                  <Typography variant="body2" fontWeight={600}>{e.email || '—'}</Typography>
                </Box>
              </Box>
            </Grid>
            <Grid item xs={6} sm={4} md={3}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <CalendarMonthIcon sx={{ fontSize: 18, color: 'error.main' }} />
                <Box>
                  <Typography variant="caption" color="textSecondary" display="block">تاریخ استخدام</Typography>
                  <Typography variant="body2" fontWeight={600}>{toJalali(e.hire_date)}</Typography>
                </Box>
              </Box>
            </Grid>
          </Grid>
        </Box>
      </Paper>

      {/* Tabs */}
      <Paper>
        <Tabs
          value={tabIndex}
          onChange={(ev, v) => setTabIndex(v)}
          variant="scrollable"
          scrollButtons="auto"
          sx={{ borderBottom: 1, borderColor: 'divider', px: 2 }}
        >
          <Tab icon={<PersonIcon />} label="اطلاعات فردی" iconPosition="start" />
          <Tab icon={<WorkIcon />} label="اطلاعات شغلی" iconPosition="start" />
          <Tab icon={<PaymentsIcon />} label="دریافتی‌ها" iconPosition="start" />
          <Tab icon={<WorkHistoryIcon />} label="کارکرد" iconPosition="start" />
          <Tab icon={<DescriptionIcon />} label="مدارک" iconPosition="start" />
        </Tabs>
        <Box sx={{ p: 3 }}>
          {tabIndex === 0 && <BasicInfoTab employee={e} />}
          {tabIndex === 1 && <EmploymentTab employee={e} />}
          {tabIndex === 2 && <ReceiptsTab employeeId={e.id} />}
          {tabIndex === 3 && <WorkRecordTab employeeId={e.id} />}
          {tabIndex === 4 && <DocumentsTab employeeId={e.id} />}
        </Box>
      </Paper>
    </Box>
  );
};

export default EmployeeProfilePage;
